import{_ as d,o as r,c as o,ag as e}from"./chunks/framework.D2veAa-g.js";const P=JSON.parse('{"title":"架构师-备考 综合知识-网络与安全-网络体系结构","description":"","frontmatter":{"title":"架构师-备考 综合知识-网络与安全-网络体系结构"},"headers":[],"relativePath":"综合知识/网络与安全/网络体系结构.md","filePath":"综合知识/网络与安全/网络体系结构.md","lastUpdated":null}'),n={name:"综合知识/网络与安全/网络体系结构.md"};function a(s,t,l,h,g,i){return r(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] OSI 七层模型（各层功能/协议/设备）</li><li>[x] TCP/IP 四层模型与 OSI 对比</li><li>[x] 网络拓扑结构（星型/总线/环型/树型/网状）</li><li>[x] 网络设备及其工作层级（集线器/交换机/路由器/网桥/防火墙）</li><li>[x] 交换技术（交换机工作流程/存储转发/洪泛/分组交换/电路交换）</li><li>[x] 路由技术（路由器功能/路由协议 IGP/EGP）</li><li>[x] 局域网/以太网/WLAN/广域网</li><li>[x] 网络工程（三层模型/综合布线 PDS）</li><li>[x] 通信技术（信道/复用/传输介质/通信方式）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、计算机网络基础" tabindex="-1">一、计算机网络基础 <a class="header-anchor" href="#一、计算机网络基础" aria-label="Permalink to &quot;一、计算机网络基础&quot;">​</a></h3><blockquote><p>计算机网络是计算机技术与通信技术相结合的产物，实现远程通信、远程信息处理和资源共享。</p></blockquote><p><strong>五大功能</strong>：数据通信、资源共享、管理集中化、实现分布式处理、负荷均衡。</p><hr><h3 id="二、网络分类与拓扑结构" tabindex="-1">二、网络分类与拓扑结构 <a class="header-anchor" href="#二、网络分类与拓扑结构" aria-label="Permalink to &quot;二、网络分类与拓扑结构&quot;">​</a></h3><p><strong>按覆盖区域分类</strong>：局域网（LAN）、无线局域网（WLAN）、城域网（MAN）、广域网（WAN）、移动通信网。</p><p><strong>五大拓扑结构：</strong></p><table tabindex="0"><thead><tr><th>拓扑</th><th>特点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>总线型</strong></td><td>所有节点共享一条通信线路</td><td>利用率低、干扰大</td></tr><tr><td><strong>星型</strong></td><td>中央节点为控制中心，任意两点通信最多两步</td><td>中央节点故障全网瘫痪</td></tr><tr><td><strong>环型</strong></td><td>信息按固定方向单向流动，两点间仅一条通路</td><td>效率低、扩充难、单点故障全网瘫痪</td></tr><tr><td><strong>树型</strong></td><td>分级集中式，节点扩充方便灵活</td><td>非叶节点故障影响大</td></tr><tr><td><strong>网状</strong></td><td>任何节点间存在通信链路</td><td>布线繁琐、成本高、控制复杂</td></tr></tbody></table><hr><h3 id="三、osi-七层模型-★" tabindex="-1">三、OSI 七层模型 ★ <a class="header-anchor" href="#三、osi-七层模型-★" aria-label="Permalink to &quot;三、OSI 七层模型 ★&quot;">​</a></h3><blockquote><p>国际标准化组织（ISO）公布的开放系统互连参考模型，共 7 层。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">层</th><th>功能</th><th>单位</th><th>协议</th><th>设备</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>7.应用层</strong></td><td>为用户提供网络服务接口</td><td>数据</td><td>HTTP、FTP、SMTP、DNS、DHCP、Telnet</td><td>网关</td></tr><tr><td style="text-align:center;"><strong>6.表示层</strong></td><td>数据格式转换、加密、压缩</td><td>—</td><td>JPEG、ASCII、MPEG、DES</td><td>网关</td></tr><tr><td style="text-align:center;"><strong>5.会话层</strong></td><td>建立/管理/终止会话，处理同步与恢复</td><td>—</td><td>RPC、SQL、NFS</td><td>网关</td></tr><tr><td style="text-align:center;"><strong>4.传输层</strong></td><td>端到端可靠透明数据传输</td><td>报文段</td><td>TCP、UDP</td><td>网关</td></tr><tr><td style="text-align:center;"><strong>3.网络层</strong></td><td>路由选择、拥塞控制、顺序控制</td><td>IP分组</td><td>IP、ICMP、IGMP、ARP、RARP</td><td><strong>路由器</strong></td></tr><tr><td style="text-align:center;"><strong>2.数据链路层</strong></td><td>组帧、点到点帧传输、差错控制、流量控制</td><td>帧</td><td>PPP、IEEE802、HDLC、ATM</td><td><strong>交换机、网桥</strong></td></tr><tr><td style="text-align:center;"><strong>1.物理层</strong></td><td>透明传输比特流、定义电气机械特性</td><td>比特</td><td>RS-232、RJ-45、V.35</td><td><strong>中继器、集线器</strong></td></tr></tbody></table><hr><h3 id="四、tcp-ip-四层模型" tabindex="-1">四、TCP/IP 四层模型 <a class="header-anchor" href="#四、tcp-ip-四层模型" aria-label="Permalink to &quot;四、TCP/IP 四层模型&quot;">​</a></h3><blockquote><p>TCP/IP 是实际使用的网络协议标准，共 4 层。</p></blockquote><table tabindex="0"><thead><tr><th>TCP/IP 四层</th><th>对应 OSI</th><th>核心协议</th></tr></thead><tbody><tr><td><strong>应用层</strong></td><td>应用层 + 表示层 + 会话层</td><td>HTTP、FTP、SMTP、DNS、DHCP、Telnet</td></tr><tr><td><strong>传输层</strong></td><td>传输层</td><td>TCP（可靠）、UDP（不可靠）</td></tr><tr><td><strong>网际层</strong></td><td>网络层</td><td>IP、ICMP、ARP、RARP、IGMP</td></tr><tr><td><strong>网络接口层</strong></td><td>数据链路层 + 物理层</td><td>Ethernet、IEEE 802.3、PPP</td></tr></tbody></table><blockquote><p>网络协议三要素：<strong>语法</strong>（数据格式）、<strong>语义</strong>（功能）、<strong>时序</strong>（顺序关系）。</p></blockquote><hr><h3 id="五、网络设备及其工作层级" tabindex="-1">五、网络设备及其工作层级 <a class="header-anchor" href="#五、网络设备及其工作层级" aria-label="Permalink to &quot;五、网络设备及其工作层级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th style="text-align:center;">工作层</th><th>核心功能</th></tr></thead><tbody><tr><td><strong>中继器</strong></td><td style="text-align:center;">物理层</td><td>接收识别信号 → 再生信号 → 发送到其他分支</td></tr><tr><td><strong>集线器</strong></td><td style="text-align:center;">物理层</td><td>从一个端口收到的数据转送到所有其他端口</td></tr><tr><td><strong>网桥</strong></td><td style="text-align:center;">数据链路层</td><td>连接多种介质和不同物理分支，包含中继器功能</td></tr><tr><td><strong>交换机</strong></td><td style="text-align:center;">数据链路层</td><td>自动寻址和交换，独享转发通路，避免端口冲突，提高吞吐量</td></tr><tr><td><strong>路由器</strong></td><td style="text-align:center;">网络层</td><td>多网络间交换和路由数据包，通过路由表进行路径选择</td></tr><tr><td><strong>防火墙</strong></td><td style="text-align:center;">—</td><td>网络门户，通过安全规则监视过滤进出数据</td></tr></tbody></table><blockquote><p><strong>冲突域 vs 广播域</strong>：路由器阻断广播域和冲突域，交换机只阻断冲突域（一个交换机整体是一个广播域），集线器整体作为一个冲突域和广播域。</p></blockquote><hr><h3 id="六、交换技术-★" tabindex="-1">六、交换技术 ★ <a class="header-anchor" href="#六、交换技术-★" aria-label="Permalink to &quot;六、交换技术 ★&quot;">​</a></h3><p><strong>交换机工作流程（&quot;学习-转发-维护&quot;）：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>1. 学习</strong></td><td>看&quot;源MAC&quot;</td><td>从收到的帧中查看源MAC地址，记录 MAC ↔ 端口 映射，启动老化计时器</td></tr><tr><td><strong>2. 转发</strong></td><td>看&quot;目的MAC&quot;</td><td>已知：单播转发到对应端口；未知/广播：洪泛到所有端口（除来源端口）；同端口：丢弃</td></tr><tr><td><strong>3. 维护</strong></td><td>MAC老化</td><td>动态表项默认 300s 未收到帧则自动删除</td></tr></tbody></table><blockquote><p>交换机初始 MAC 地址表为<strong>空</strong>，通过学习<strong>源MAC地址</strong>添加表项。</p></blockquote><p><strong>常见交换方式：</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>特点</th><th>典型应用</th></tr></thead><tbody><tr><td><strong>分组交换</strong></td><td>数据分割为分组独立路由，无连接、健壮性强、效率高</td><td><strong>Internet 核心</strong>（IP网络）</td></tr><tr><td><strong>电路交换</strong></td><td>建立专用物理通路，资源独占、延迟小、线路利用率低</td><td>传统电话网络（PSTN）</td></tr><tr><td><strong>虚电路交换</strong></td><td>分组交换的一种，先建立逻辑连接，分组沿固定路径传输</td><td>X.25、帧中继、ATM</td></tr><tr><td><strong>消息交换</strong></td><td>以整个报文为单位的存储转发</td><td>已基本淘汰（电报网络）</td></tr></tbody></table><hr><h3 id="七、路由技术" tabindex="-1">七、路由技术 <a class="header-anchor" href="#七、路由技术" aria-label="Permalink to &quot;七、路由技术&quot;">​</a></h3><p><strong>路由器功能</strong>：异种网络互连、子网协议转换、数据路由、速率适配、隔离网络（防广播风暴）、报文分片和重组、备份与流量控制。</p><p><strong>路由协议分类：</strong></p><ul><li><strong>IGP</strong>（内部网关协议）：同一自治系统内</li><li><strong>EGP</strong>（外部网关协议）：不同自治系统间</li></ul><hr><h3 id="八、局域网与以太网" tabindex="-1">八、局域网与以太网 <a class="header-anchor" href="#八、局域网与以太网" aria-label="Permalink to &quot;八、局域网与以太网&quot;">​</a></h3><p><strong>以太网标准 IEEE 802.3：</strong></p><table tabindex="0"><thead><tr><th>标准</th><th>类型</th><th>速率</th><th>传输介质</th></tr></thead><tbody><tr><td>IEEE 802.3</td><td>标准以太网</td><td>10Mb/s</td><td>细同轴电缆</td></tr><tr><td>IEEE 802.3u</td><td>快速以太网</td><td>100Mb/s</td><td>双绞线</td></tr><tr><td>IEEE 802.3z</td><td>千兆以太网</td><td>1000Mb/s</td><td>光纤/双绞线</td></tr><tr><td>IEEE 802.3ae</td><td>万兆以太网</td><td>10Gb/s</td><td>光纤</td></tr></tbody></table><blockquote><p>最小帧长：<strong>64 字节</strong>。WLAN 技术标准：<strong>IEEE 802.11</strong>。</p></blockquote><hr><h3 id="九、网络工程" tabindex="-1">九、网络工程 <a class="header-anchor" href="#九、网络工程" aria-label="Permalink to &quot;九、网络工程&quot;">​</a></h3><p><strong>三层模型：</strong></p><table tabindex="0"><thead><tr><th>层</th><th>功能</th></tr></thead><tbody><tr><td><strong>核心层</strong></td><td>提供不同区域之间的最佳路由和<strong>高速数据传送</strong></td></tr><tr><td><strong>汇聚层</strong></td><td>连接接入层，实施安全、流量、负载和路由相关策略</td></tr><tr><td><strong>接入层</strong></td><td>用户本地网段访问，收集用户信息（IP/MAC/日志），用户管理（认证/计费）</td></tr></tbody></table><p><strong>建筑物综合布线系统（PDS）6个子系统：</strong> 工作区子系统 → 水平布线子系统 → 设备间子系统 → 垂直干线子系统 → 管理子系统 → 建筑群子系统</p><hr><h3 id="十、通信技术" tabindex="-1">十、通信技术 <a class="header-anchor" href="#十、通信技术" aria-label="Permalink to &quot;十、通信技术&quot;">​</a></h3><p><strong>传输介质：</strong></p><table tabindex="0"><thead><tr><th>介质</th><th>类型</th><th>特点</th></tr></thead><tbody><tr><td><strong>双绞线</strong></td><td>UTP（无屏蔽）</td><td>价格低、安装简单；CAT3→10M、CAT5→100M、CAT5E/CAT6→1000M；传输距离 100m 内</td></tr><tr><td></td><td>STP（屏蔽）</td><td>可靠性高，价格贵，安装麻烦</td></tr><tr><td><strong>光纤</strong></td><td>多模（MMF）</td><td>LED光源、成本低、短距离（100Mbps时2KM，1000Mbps时550m）</td></tr><tr><td></td><td>单模（SMF）</td><td><strong>LD激光源</strong>、成本高、传输距离远（5KM）、可靠性高</td></tr></tbody></table><p><strong>通信方向</strong>：单工（单向）、半双工（双向但不能同时）、全双工（双向同时）。</p><p><strong>同步方式</strong>：异步传输（字符级+起止位）、同步传输（数据块级+同步帧）、串行传输（一根数据线）、并行传输（多根数据线）。</p><p><strong>复用技术</strong>：TDM（时分复用）、FDM（频分复用）、CDM（码分复用）。 <strong>多址技术</strong>：TDMA（时分多址）、FDMA（频分多址）、CDMA（码分多址）。</p>',53)])])}const c=d(n,[["render",a]]);export{P as __pageData,c as default};
